/**
 * AI action registry — types.
 *
 * Generated by slice S1 of the TManage AI connector (MCP). See
 * `MCP-CONNECTOR-PLAN-2026-10-20.md` §2, §7 (S1) and
 * `MCP-CONNECTOR-ARCHITECTURE-2026-10-20.md` B3 / T-REG-01.
 *
 * This is the route *inventory and classification skeleton*. Every one of the
 * 710 live API routes is accounted for exactly once: either as an op here or as
 * a `NEVER` deny-list entry. `registry-sync.test.ts` enumerates the live routes
 * by reflection and fails if any route is unclassified, double-classified, or
 * carries a capability that disagrees with its op. Slices S2–S4 add the zod
 * input/output schemas, redaction profiles, titles, descriptions and examples
 * to each op; this slice fixes only id, method, path, capability, risk and scope.
 */
import type { Capability } from '@tmanage/domain';

/** HTTP methods the API actually serves (no ALL/OPTIONS/HEAD among the 710 routes). */
export const HTTP_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'] as const;
export type HttpMethod = (typeof HTTP_METHODS)[number];

/**
 * Risk class of an AI-exposable op (plan §2).
 * - `read`    — a read; runs at once under the `read` scope.
 * - `write`   — an ordinary edit within the member's own rights; runs at once under `write`.
 * - `confirm` — needs a human approval outside the model (plan §4.3) before it runs.
 * A fourth class, "never", is not a risk but the absence of an op: those routes live in `NEVER`.
 */
export const RISK_CLASSES = ['read', 'write', 'confirm'] as const;
export type RiskClass = (typeof RISK_CLASSES)[number];

/** Consent scopes (plan §4.2). A scope only ever *narrows* access. */
export const AI_SCOPES = ['read', 'write', 'manage', 'billing'] as const;
export type AiScope = (typeof AI_SCOPES)[number];

/** Why a live route is withheld from the AI surface entirely (plan §2, architecture B3). */
export const NEVER_REASONS = [
  'admin_security',
  'audit_retention',
  'auth',
  'automation_secrets',
  'billing_seat_change',
  'billing_subscription_change',
  'google_auth',
  'invitation',
  // S13. The connector's own discovery and distribution surface — `GET /openapi/ai.json`
  // (the OpenAPI 3.1 description of the AI action surface) and `GET /downloads/tmanage-mcp.tgz`
  // (the downloadable stdio bridge). Both are `@Public()` and `@NoTenant()`: they are served
  // before any sign-in and are never an AI-driven tool, so they are withheld from the surface.
  'mcp_discovery',
  'mcp_endpoint',
  // 0208 / S7. The OAuth 2.1 authorization server and its discovery metadata — the connector's
  // own front door. An AI principal must never drive sign-in, consent, token minting or client
  // registration as a tool (architecture B3: it cannot create PATs or OAuth clients or change
  // its own grant). These routes are public and session-establishing, not org-scoped actions.
  'oauth',
  'org_creation_or_account',
  'org_security_manage',
  'platform_admin',
  'policy_definitions',
  'public_site',
  'public_upload_part',
  'role_definitions',
  'session',
  'setup',
  'signup',
  // 0210. Connecting, configuring or disconnecting the company's Google Drive, the OAuth
  // callback, the picker's short-lived Google token and the upload session URL: each mints,
  // holds or hands out a third-party credential, which an AI principal must never drive.
  'storage_connection',
] as const;
export type NeverReason = (typeof NEVER_REASONS)[number];

/**
 * A single AI-exposable operation. S1 populates the classification fields only;
 * S2–S4 add the schema/redaction/presentation fields (kept optional here so the
 * skeleton type-checks before those slices land).
 */
export interface AiActionOp {
  /** Stable registry id, e.g. `work.item.create`. Never a path — `run_action` takes this id. */
  readonly id: string;
  readonly method: HttpMethod;
  /** The Nest route path, including `:params` — the key the sync test matches against. */
  readonly path: string;
  /** The route's `@RequireCapability`, mirrored here so the sync test can detect drift. */
  readonly capability: Capability | null;
  readonly risk: RiskClass;
  readonly scope: AiScope;
}

/** A route withheld from the AI surface (architecture B3 deny-list). */
export interface NeverEntry {
  readonly method: HttpMethod;
  readonly path: string;
  readonly reason: NeverReason;
}

/** The canonical key for a route: `"<METHOD> <path>"`. */
export type RouteKey = `${HttpMethod} ${string}`;

export function routeKey(method: string, path: string): RouteKey {
  return `${method.toUpperCase()} ${path}` as RouteKey;
}
